<?php
namespace App\Services\Sales;
use App\Models\{AgentCommission,CorporateAccount,CorporateInvoice,CorporatePayment,LocalPurchaseOrder,TravelAgent};
use App\Services\Accounting\AccountingService;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;
class CorporateSalesService{
 public function __construct(private AccountingService $accounting){}
 public function outstandingForCompany(int $propertyId,int $companyId):float{return (float)CorporateInvoice::where('property_id',$propertyId)->where('corporate_account_id',$companyId)->sum('balance');}
 public function outstandingForAgent(int $propertyId,int $agentId):float{return (float)CorporateInvoice::where('property_id',$propertyId)->where('travel_agent_id',$agentId)->sum('balance');}
 public function ensureCredit(?CorporateAccount $company,?TravelAgent $agent,float $newAmount):void{$entity=$company?:$agent;if(!$entity)return;$limit=(float)$entity->credit_limit;if($limit<=0)return;$out=$company?$this->outstandingForCompany($entity->property_id,$entity->id):$this->outstandingForAgent($entity->property_id,$entity->id);if($out+$newAmount>$limit)throw new RuntimeException('Credit limit exceeded. Available credit: UGX '.number_format(max(0,$limit-$out),2));}
 public function createInvoice(array $data,array $items,int $userId):CorporateInvoice{return DB::transaction(function()use($data,$items,$userId){$company=!empty($data['corporate_account_id'])?CorporateAccount::findOrFail($data['corporate_account_id']):null;$agent=!empty($data['travel_agent_id'])?TravelAgent::findOrFail($data['travel_agent_id']):null;$subtotal=0;$tax=0;foreach($items as $i){$line=(float)$i['quantity']*(float)$i['unit_price'];$subtotal+=$line;$tax+=(float)($i['tax_amount']??0);}$total=$subtotal+$tax;$this->ensureCredit($company,$agent,$total);$lpo=null;if(!empty($data['local_purchase_order_id'])){$lpo=LocalPurchaseOrder::lockForUpdate()->findOrFail($data['local_purchase_order_id']);if($lpo->status!=='open'||(float)$lpo->used_amount+$total>(float)$lpo->authorised_amount)throw new RuntimeException('LPO does not have enough authorised balance.');$lpo->increment('used_amount',$total);if((float)$lpo->fresh()->used_amount >= (float)$lpo->authorised_amount)$lpo->update(['status'=>'fully_used']);}$inv=CorporateInvoice::create([...$data,'invoice_no'=>$data['invoice_no']??'CINV-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'invoice_date'=>$data['invoice_date']??now()->toDateString(),'subtotal'=>$subtotal,'tax_total'=>$tax,'total'=>$total,'balance'=>$total,'created_by'=>$userId]);foreach($items as $i)$inv->items()->create([...$i,'line_total'=>(float)$i['quantity']*(float)$i['unit_price']+(float)($i['tax_amount']??0)]);$this->accounting->post($inv->property_id,'corporate_invoice',$inv->id,'Corporate/agent invoice '.$inv->invoice_no,[['code'=>'1100','debit'=>$total],['code'=>'4400','credit'=>$subtotal],...($tax>0?[['code'=>'2100','credit'=>$tax]]:[])],$userId);return $inv;});}
 public function pay(CorporateInvoice $invoice,array $data,int $userId):CorporatePayment{return DB::transaction(function()use($invoice,$data,$userId){$invoice->refresh();$amount=(float)$data['amount'];if($amount<=0||$amount>(float)$invoice->balance)throw new RuntimeException('Payment exceeds invoice balance.');$p=$invoice->payments()->create(['property_id'=>$invoice->property_id,'payment_date'=>$data['payment_date']??now()->toDateString(),'method'=>$data['method'],'amount'=>$amount,'reference'=>$data['reference']??null,'received_by'=>$userId]);$paid=(float)$invoice->payments()->sum('amount');$balance=max(0,(float)$invoice->total-$paid);$invoice->update(['paid_total'=>$paid,'balance'=>$balance,'status'=>$balance<=0?'paid':($paid>0?'partially_paid':'open')]);$cashCode=match($p->method){'cash'=>'1000','mtn_momo'=>'1020','airtel_money'=>'1030',default=>'1010'};$this->accounting->post($invoice->property_id,'corporate_payment',$p->id,'Corporate payment '.$invoice->invoice_no,[['code'=>$cashCode,'debit'=>$amount],['code'=>'1100','credit'=>$amount]],$userId);return $p;});}
 public function accrueCommission(TravelAgent $agent,?int $reservationId,?int $eventId,float $base):AgentCommission{return DB::transaction(function()use($agent,$reservationId,$eventId,$base){$pct=(float)$agent->commission_percent;$amount=round($base*$pct/100,2);return AgentCommission::firstOrCreate(['property_id'=>$agent->property_id,'travel_agent_id'=>$agent->id,'reservation_id'=>$reservationId,'hotel_event_id'=>$eventId],['base_amount'=>$base,'commission_percent'=>$pct,'commission_amount'=>$amount,'status'=>'accrued']);});}
}
